describe('Remove individual filter tags', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-input"]').type('test query');
    cy.get('[data-testid="filter-button"]').click();
    cy.get('[data-testid="filter-option-category"]').click();
    cy.get('[data-testid="filter-option-price"]').click();
    cy.get('[data-testid="apply-filters-button"]').click();
  });

  it('should remove a single filter tag when clicking the x icon', () => {
    cy.get('[data-testid="filter-tag"]').should('have.length', 2);
    cy.get('[data-testid="filter-tag-remove-icon"]').first().click();
    cy.get('[data-testid="filter-tag"]').should('have.length', 1);
    cy.get('[data-testid="filter-tag"]').should('contain', 'Price');
  });

  it('should remove all filter tags one by one', () => {
    cy.get('[data-testid="filter-tag"]').should('have.length', 2);
    cy.get('[data-testid="filter-tag-remove-icon"]').first().click();
    cy.get('[data-testid="filter-tag"]').should('have.length', 1);
    cy.get('[data-testid="filter-tag-remove-icon"]').click();
    cy.get('[data-testid="filter-tag"]').should('have.length', 0);
    cy.get('[data-testid="no-filters-message"]').should('be.visible');
  });

  it('should update search results after removing a filter tag', () => {
    cy.get('[data-testid="search-result"]').should('have.length.greaterThan', 0);
    const initialResultCount = cy.get('[data-testid="search-result"]').its('length');
    cy.get('[data-testid="filter-tag-remove-icon"]').first().click();
    cy.get('[data-testid="search-result"]').should('have.length.greaterThan', 0);
  });

  it('should handle removing filter tag when only one filter is applied', () => {
    cy.get('[data-testid="filter-tag-remove-icon"]').first().click();
    cy.get('[data-testid="filter-tag"]').should('have.length', 1);
    cy.get('[data-testid="filter-tag-remove-icon"]').click();
    cy.get('[data-testid="filter-tag"]').should('not.exist');
    cy.get('[data-testid="search-input"]').should('have.value', 'test query');
  });
});
